CREATE TABLE interpretation_records(input_id uuid PRIMARY KEY REFERENCES ingestion_inputs,project_id uuid NOT NULL,run_id uuid NOT NULL,status text NOT NULL,transcript text,transcript_reference uuid,result jsonb,metadata jsonb NOT NULL DEFAULT '{}',error text,question_count integer NOT NULL DEFAULT 0,answer_text text,FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE interpretation_clarifications(id uuid PRIMARY KEY,input_id uuid NOT NULL REFERENCES ingestion_inputs,project_id uuid NOT NULL,run_id uuid NOT NULL,clarification jsonb NOT NULL,status text NOT NULL,question_count integer NOT NULL,FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
CREATE TABLE live_interactions(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,agent_id text NOT NULL,thread_id text NOT NULL,tool_call_id text NOT NULL UNIQUE,proposal_id uuid NOT NULL,proposal_version integer NOT NULL,expected_hash text NOT NULL,expires_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('pending','approved','rejected','expired','invalidated')),UNIQUE(run_id,proposal_id,proposal_version),FOREIGN KEY(run_id,project_id) REFERENCES scenario_runs(id,project_id));
